CREATE OR REPLACE FUNCTION public.fn_get_recent_parent_communications(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, classroom_id uuid, child_id uuid, recipient_person_id uuid, recipient_user_id uuid, recipient_email character varying, recipient_name character varying, recipient_relationship character varying, communication_type character varying, reporting_date_start date, reporting_date_end date, title character varying, content_draft text, content_final text, family_conversation_starter text, evidence_summary_json jsonb, consent_verified boolean, consent_notes character varying, status character varying, teacher_id uuid, teacher_name character varying, approved_by_user_id uuid, approved_at timestamp with time zone, sent_at timestamp with time zone, delivery_channel character varying, delivery_status character varying, delivery_error text, idempotency_key character varying, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text, classroom_name character varying, branch_name character varying, branch_id uuid)  LANGUAGE sql  STABLE AS $function$     SELECT          pc.id, pc.tenant_id, pc.organization_id, pc.classroom_id, pc.child_id,         pc.recipient_person_id, pc.recipient_user_id, pc.recipient_email, pc.recipient_name, pc.recipient_relationship,         pc.communication_type, pc.reporting_date_start, pc.reporting_date_end,         pc.title, pc.content_draft, pc.content_final, pc.family_conversation_starter,         pc.evidence_summary_json, pc.consent_verified, pc.consent_notes,         pc.status, pc.teacher_id, pc.teacher_name, pc.approved_by_user_id, pc.approved_at, pc.sent_at,         pc.delivery_channel, pc.delivery_status, pc.delivery_error, pc.idempotency_key,         pc.created_at, pc.updated_at,         TRIM(CONCAT(c.first_name, ' ', c.last_name)) AS child_name,         cl.name AS classroom_name,         b.name AS branch_name,         cl.branch_id     FROM parent_communications pc     JOIN children c ON pc.child_id = c.id     LEFT JOIN classrooms cl ON pc.classroom_id = cl.id     LEFT JOIN branches b ON cl.branch_id = b.id     WHERE pc.tenant_id = p_tenant_id       AND (p_organization_id IS NULL OR pc.organization_id = p_organization_id)       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR pc.classroom_id = p_classroom_id)     ORDER BY pc.created_at DESC     LIMIT p_limit; $function$ ;
